parameters.jsCode:
const items = $input.all();
const webhookData = $('Webhook').first().json;

const results = items.map(item => {
  // Check for API errors
  if (item.json.error) {
    return {
      json: {
        success: false,
        error: {
          code: item.json.error.code || 500,
          message: item.json.error.message || 'OpenAI API error',
          status: 'API_ERROR'
        },
        meta: {
          provider: 'openai',
          execution_mode: webhookData.body.execution_mode || 'online'
        }
      }
    };
  }

  try {
    const content = item.json.choices?.[0]?.message?.content || '{}';
    const parsed = JSON.parse(content);

    // Calculate some statistics
    const syllabus = parsed.syllabus || parsed;
    const stats = {
      total_modules: syllabus.modules?.length || 0,
      total_lessons: syllabus.modules?.reduce((sum, m) => sum + (m.lessons?.length || 0), 0) || 0,
      total_hours: syllabus.duration?.total_hours || syllabus.modules?.reduce((sum, m) => sum + (m.duration_hours || 0), 0) || 0
    };

    return {
      json: {
        success: true,
        data: {
          ...parsed,
          statistics: stats
        },
        meta: {
          provider: 'openai',
          model: item.json.model || webhookData.body.model || 'gpt-4o',
          execution_mode: webhookData.body.execution_mode || 'online',
          tokens_used: item.json.usage?.total_tokens || 0
        }
      }
    };
  } catch (e) {
    return {
      json: {
        success: false,
        error: {
          code: 500,
          message: 'Failed to parse syllabus response: ' + e.message,
          status: 'PARSE_ERROR'
        },
        meta: {
          provider: 'openai',
          execution_mode: webhookData.body.execution_mode || 'online'
        }
      }
    };
  }
});

return results;
